def quantidade(texto):
    try:
        valor = int(texto)
    except ValueError:
        return None
    if valor < 0:
        return None
    return valor

for entrada in ['8', 'oito', '-2', '0']:
    print(quantidade(entrada))

WITH alunos(id, nome) AS (
    VALUES (1, 'Bia'), (2, 'Caio'), (3, 'Dani')
), sessoes(aluno_id, minutos) AS (
    VALUES (1, 10), (1, 20), (2, 15)
)
SELECT a.nome, s.minutos
FROM alunos AS a
JOIN sessoes AS s ON s.aluno_id = a.id
ORDER BY a.id, s.minutos;
